package android.content;
public class ClipDescription { public static final String MIMETYPE_TEXT_PLAIN="text/plain", MIMETYPE_TEXT_HTML="text/html", MIMETYPE_TEXT_URILIST="text/uri-list", MIMETYPE_TEXT_INTENT="text/vnd.android.intent"; private final CharSequence label; private final String[] types; public ClipDescription(CharSequence l,String[] t) { label=l; types=t; } public CharSequence getLabel() { return label; } public int getMimeTypeCount() { return types.length; } public String getMimeType(int i) { return types[i]; } public boolean hasMimeType(String t) { for(String x:types) if(x.equals(t) || t.equals("*/*")) return true; return false; } }
